            <div class="faq-answer">القرار يعتمد على عدة أمور معاً: مقدار الإزاحة، والعمر، والذراع المصابة، وحدوث خلع، ونوع الرياضة ومستواها. والأدلة العلمية تدعم الخيارين في كثير من الحالات، لذلك يختلف القرار من طفل لآخر.</div>
