            <p>للمراهقين (12+ سنة أو وزن فوق 50 كغ). مسمار معدني صلب يُدخل من أعلى الفخذ (المدور الكبير) وينزل عبر القناة النخاعية ويُثبت بمسامير قفل في الأعلى والأسفل. يعطي ثباتاً ممتازاً ويسمح بالتحميل المبكر. مهم: يُستخدم مدخل المدور الكبير (وليس الفتحة الكمثرية) لتجنب إصابة التروية الدموية لرأس الفخذ عند الأطفال الذين لم يكتمل نموهم.</p>
