            <div class="illustration-caption">صورة من داخل الركبة أثناء العملية بالمنظار: خيوط قوية تمر عبر ألياف الرباط الصليبي الأمامي (ACL) إلى نفق صغير في عظم الساق، فتعيد القطعة العظمية (Fragment) إلى مكانها.</div>
