            <div class="faq-answer">نادراً. معظم كسور مشط القدم بعيدة عن مناطق النمو أو لا تؤثر عليها، ويعود الطفل إلى المشي والرياضة بشكل طبيعي. إذا مر الكسر عبر صفيحة النمو فقد يتابعه الطبيب لفترة أطول. اقرؤوا المزيد في صفحة <a href="#" class="page-link" data-goto="growth-plate-fracture">كسور صفيحة النمو</a>.</div>
